/* The retail 68000 SUB.L wraps at 32 bits.  Signed subtraction in C
 * invokes undefined behavior on overflow; decode the unsigned 32-bit
 * difference back to its exact signed two's-complement value. */
static s32 wrapped_delta(s32 to,s32 from)
{
    u32 d=(u32)to-(u32)from;
    return d<=0x7fffffffu ? (s32)d : (s32)((s64)d-INT64_C(4294967296));
}

/* COLLIDE.S AMPCollisions uses SUB.L followed by conditional NEG.L.
 * Both 68000 operations wrap as 32-bit words; in particular NEG.L on
 * $80000000 leaves that same signed word. C signed subtraction and
 * negation can overflow, so reproduce the original register result with
 * unsigned arithmetic before interpreting its sign. */
static s32 wrapped_abs_delta(s32 to,s32 from)
{
    u32 d=(u32)to-(u32)from;
    if(d&0x80000000u)d=0u-d;
    return d<=0x7fffffffu ? (s32)d : (s32)((s64)d-INT64_C(4294967296));
}

